import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { deleteMeet } from "../handlers/deleteMeet";
import type { ApiError } from "../runtime/client";
import type { SpaceMeetEntityType } from "../types/SpaceMeetEntityType";
import type { SpacePartition } from "../types/SpacePartition";

type Data = Awaited<ReturnType<typeof deleteMeet>>;
type Vars = { spacePk: SpacePartition; meetSk: SpaceMeetEntityType };

export function useDeleteMeet(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => deleteMeet(vars.spacePk, vars.meetSk),
    ...options,
  });
}
